const emptyTask={title:'',description:'',phaseKey:'general',assigneeUserId:'',participantUserIds:[],get dueMode(){return routeNewDate()?'fixed':'relative'},get fixedDate(){return routeNewDate()},offsetDays:-30,priority:'normal',dependencyIds:[],approvalId:null,selectionId:null,fileIds:[]};
