function useOnline(){const [value,setValue]=useState(typeof navigator==='undefined'||navigator.onLine!==false);useEffect(()=>{const update=()=>setValue(navigator.onLine!==false);window.addEventListener('online',update);window.addEventListener('offline',update);return()=>{window.removeEventListener('online',update);window.removeEventListener('offline',update)}},[]);return value}
function money(value){return value===null||value===''||value===undefined?'Цена не согласована':new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(Number(value)/100)}
