function Actions({busy,onClose,label='Сохранить'}){return <div className="dialog-actions"><button type="button" className="button quiet" onClick={onClose}>Отмена</button><button className="button" disabled={busy}>{busy?'Сохраняем…':label}</button></div>}
function Pager({page,offset,load}){if(!page?.total||page.total<=page.limit)return null;return <nav className="v2-workflow-pager"><button disabled={!offset} onClick={()=>load(Math.max(0,offset-page.limit))}>Назад</button><span>{offset+1}–{Math.min(offset+page.limit,page.total)} из {page.total}</span><button disabled={page.nextOffset===null} onClick={()=>load(page.nextOffset)}>Дальше</button></nav>}

